(4959293, 722210, 64670, '<td valign="top">Dark, sinister, but so very, VERY well done!<br/> <br/>I''ll need to sleep with my eyes open tonight - SMILE!</td>', 'Dark, sinister, but so very, VERY well done! I''ll need to sleep with my eyes open tonight - SMILE!', '2008-09-17 05:58:36.000000', NULL, 1),
