(4959299, 721978, 92296, '<td valign="top">Shame the lines of the steps don''t match those on the house.  Also find the inclusion of half the window a little distracting - all or nothing might work better.  Nice lines of the ladder itself and the makings of a good composition.</td>', 'Shame the lines of the steps don''t match those on the house.  Also find the inclusion of half the window a little distracting - all or nothing might work better.  Nice lines of the ladder itself and the makings of a good composition.', '2008-09-17 06:12:02.000000', NULL, 1),
(4959301, 721859, 92296, '<td valign="top">Do you work for Lehman Brothers?</td>', 'Do you work for Lehman Brothers?', '2008-09-17 06:13:52.000000', NULL, 1),
(4959303, 721146, 92296, '<td valign="top">Like this a lot.  Would like it even more if I could see more of the drop below him, but nice perspective, lines and capture 8</td>', 'Like this a lot.  Would like it even more if I could see more of the drop below him, but nice perspective, lines and capture 8', '2008-09-17 06:15:33.000000', NULL, 1),
