(4959323, 721960, 92296, '<td valign="top">If you cropped out the building on the right, I''d this a lot more.  Nice tone and composition.</td>', 'If you cropped out the building on the right, I''d this a lot more.  Nice tone and composition.', '2008-09-17 06:39:55.000000', NULL, 1),
(4959326, 722210, 92296, '<td valign="top">Very sinister, really well lit. There''s something about the look in the eye and the glove that suggests he''s moving in for a full body search, but I try not to hold that thought. 9</td>', 'Very sinister, really well lit. There''s something about the look in the eye and the glove that suggests he''s moving in for a full body search, but I try not to hold that thought. 9', '2008-09-17 06:42:22.000000', NULL, 1),
