(4960418, 721986, 47470, '<td valign="top">It''s pretty difficult to photograph something so flat since you can''t get any shadows.  Maybe painting with light to spotlight a certain word or phrase would have made the lighting more appealing.  I also might have tilted the page a bit more so that the main headline doesn''t look so straight.</td>', 'It''s pretty difficult to photograph something so flat since you can''t get any shadows.  Maybe painting with light to spotlight a certain word or phrase would have made the lighting more appealing.  I also might have tilted the page a bit more so that the main headline doesn''t look so straight.', '2008-09-17 17:48:16.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4960420, 722251, 77192, '<td valign="top">nice silhouette but I''m not seeing the risk here. You could do with a bit more contrast in your shot.</td>', 'nice silhouette but I''m not seeing the risk here. You could do with a bit more contrast in your shot.', '2008-09-17 17:48:23.000000', NULL, 1),
(4960422, 722210, 47470, '<td valign="top">Great job at setting the mood.</td>', 'Great job at setting the mood.', '2008-09-17 17:49:07.000000', NULL, 1),
(4960423, 720911, 77192, '<td valign="top">Needs to be sharper, with much less noise.</td>', 'Needs to be sharper, with much less noise.', '2008-09-17 17:49:14.000000', NULL, 1),
(4960427, 721317, 77192, '<td valign="top">I was wondering if someone would do this. It was my first idea, but I dismissed it on the grounds everyone else would do it hehe.<br/> <br/>I think you''ve got too many fallen pieces there, you almost don''t see the one remaining standing piece.</td>', 'I was wondering if someone would do this. It was my first idea, but I dismissed it on the grounds everyone else would do it hehe. I think you''ve got too many fallen pieces there, you almost don''t see the one remaining standing piece.', '2008-09-17 17:51:06.000000', NULL, 1),
(4960453, 720988, 47470, '<td valign="top">I think this might have worked better in color.</td>', 'I think this might have worked better in color.', '2008-09-17 18:01:32.000000', NULL, 1),
(4960457, 721330, 47470, '<td valign="top">Nice capture of the smoke, but the light looks a bit harsh on his face.</td>', 'Nice capture of the smoke, but the light looks a bit harsh on his face.', '2008-09-17 18:02:34.000000', NULL, 1),
(4960459, 722137, 47470, '<td valign="top">I''m not sure if the colors help the photo.</td>', 'I''m not sure if the colors help the photo.', '2008-09-17 18:03:12.000000', NULL, 1),
(4960482, 721899, 47470, '<td valign="top">Nice idea.  Made me laugh : )</td>', 'Nice idea.  Made me laugh : )', '2008-09-17 18:27:49.000000', NULL, 1),
(4960497, 722279, 47470, '<td valign="top">I think this might have looked better in color, especially with a pretty red apple against the green trees in the background.  The lighting looks like it came from an on-camera flash, but natural lighting might have been a bit more appealing.</td>', 'I think this might have looked better in color, especially with a pretty red apple against the green trees in the background.  The lighting looks like it came from an on-camera flash, but natural lighting might have been a bit more appealing.', '2008-09-17 18:43:30.000000', NULL, 1),
(4960500, 721885, 47470, '<td valign="top">This shot would have looked better with different lighting.  It looks like you used an on-camera flash, and that makes the hand a bit too bright for my taste.</td>', 'This shot would have looked better with different lighting.  It looks like you used an on-camera flash, and that makes the hand a bit too bright for my taste.', '2008-09-17 18:44:50.000000', NULL, 1),
