(4962514, 722279, 97936, '<td valign="top">I like the creative framing here.  Nice.</td>', 'I like the creative framing here.  Nice.', '2008-09-18 19:32:49.000000', NULL, 1),
(4962515, 721758, 27481, '<td valign="top">ya your definitely right, that''s a risk i don''t ever want to take (LMAO)<br/>ps: but am sure your model cleans up pretty good</td>', 'ya your definitely right, that''s a risk i don''t ever want to take (LMAO)ps: but am sure your model cleans up pretty good', '2008-09-18 19:32:53.000000', NULL, 1),
(4962557, 721986, 97936, '<td valign="top">I don''t think there''s anything really creative in this photograph that you couldn''t get from the paper itself.  Even the DOF just points to the text that the paper already highlighted.</td>', 'I don''t think there''s anything really creative in this photograph that you couldn''t get from the paper itself.  Even the DOF just points to the text that the paper already highlighted.', '2008-09-18 19:42:47.000000', NULL, 1),
(4962575, 722266, 97936, '<td valign="top">I like the grass coming back in at the top of the frame to fill that empty space in the sky.</td>', 'I like the grass coming back in at the top of the frame to fill that empty space in the sky.', '2008-09-18 19:46:38.000000', NULL, 1),
(4962584, 721906, 97936, '<td valign="top">Nice framing.</td>', 'Nice framing.', '2008-09-18 19:48:32.000000', NULL, 1),
(4962597, 721703, 89494, '<td valign="top">:) it''s funny</td>', ':) it''s funny', '2008-09-18 19:53:10.000000', NULL, 1),
(4962602, 720388, 89494, '<td valign="top">interesting view. maybe the angle is not right but it has a certain impact</td>', 'interesting view. maybe the angle is not right but it has a certain impact', '2008-09-18 19:54:36.000000', NULL, 1),
(4962604, 721132, 89494, '<td valign="top">wow. it looks nice.</td>', 'wow. it looks nice.', '2008-09-18 19:57:38.000000', NULL, 1),
