(4962721, 720711, 62187, '<td valign="top">I think a sharper focus would have sent this photo over the top.</td>', 'I think a sharper focus would have sent this photo over the top.', '2008-09-18 21:08:49.000000', NULL, 1),
(4962722, 721865, 67540, '<td valign="top">seems like a snapshot, very candid air</td>', 'seems like a snapshot, very candid air', '2008-09-18 21:08:52.000000', NULL, 1),
