(4962743, 721255, 67540, '<td valign="top">risk?</td>', 'risk?', '2008-09-18 21:14:33.000000', NULL, 1),
(4962744, 720388, 78638, '<td valign="top">IMHO, The concept is great, but I think the image would have more impact if you could get the head more in focus, or take the head out altogether.</td>', 'IMHO, The concept is great, but I think the image would have more impact if you could get the head more in focus, or take the head out altogether.', '2008-09-18 21:14:51.000000', NULL, 1),
(4962746, 722061, 67540, '<td valign="top">If it''s air racing, maybe include who they''re racing against?  Or whatever path they must fly on?</td>', 'If it''s air racing, maybe include who they''re racing against?  Or whatever path they must fly on?', '2008-09-18 21:15:19.000000', NULL, 1),
(4962748, 722169, 67540, '<td valign="top">high contrast doesn''t mean an automatically amazing image</td>', 'high contrast doesn''t mean an automatically amazing image', '2008-09-18 21:15:46.000000', NULL, 1),
(4962749, 721796, 67540, '<td valign="top">Lots of gambling images, need to make yours truly amazing to stand out</td>', 'Lots of gambling images, need to make yours truly amazing to stand out', '2008-09-18 21:16:05.000000', NULL, 1),
(4962751, 721315, 67540, '<td valign="top">where''d all the other colors go?  Just because you bump some contrast, saturation, levels or whatever doesn''t it make it a better image</td>', 'where''d all the other colors go?  Just because you bump some contrast, saturation, levels or whatever doesn''t it make it a better image', '2008-09-18 21:16:44.000000', NULL, 1),
