(4962754, 720388, 67540, '<td valign="top">thought that was a rock at first glance, not someone''s head... maybe try showing more of the person or none of them at all</td>', 'thought that was a rock at first glance, not someone''s head... maybe try showing more of the person or none of them at all', '2008-09-18 21:18:03.000000', NULL, 1),
(4962922, 721315, 62187, '<td valign="top">Can''t figure out why it''s so dark: did you change the brightness in post editing or is your camera exposure setting in the wrong range? Regardless, ''Flying High'' is certainly a ''Risk''.</td>', 'Can''t figure out why it''s so dark: did you change the brightness in post editing or is your camera exposure setting in the wrong range? Regardless, ''Flying High'' is certainly a ''Risk''.', '2008-09-18 22:20:39.000000', NULL, 1),
(4962930, 721876, 62187, '<td valign="top">If this end were in the socket then I''d say yes, keep the other end away from water. As it goes this way, I see no risk. I also see some signs of oversharpening along the prongs but the contrasting colors are nice.</td>', 'If this end were in the socket then I''d say yes, keep the other end away from water. As it goes this way, I see no risk. I also see some signs of oversharpening along the prongs but the contrasting colors are nice.', '2008-09-18 22:24:33.000000', NULL, 1),
(4962938, 722280, 62187, '<td valign="top">Sky High...what''s the risk in that...are you Sky High as in stoned? No, I guess not. A nice photo: I imagine the risk is standing on some high ledge.</td>', 'Sky High...what''s the risk in that...are you Sky High as in stoned? No, I guess not. A nice photo: I imagine the risk is standing on some high ledge.', '2008-09-18 22:26:57.000000', NULL, 1),
(4962941, 722395, 62187, '<td valign="top">I just happened to check my 401k today: I''m not happy. I guess your photo evokes emotive thoughts. Plus, it''s very good: 10</td>', 'I just happened to check my 401k today: I''m not happy. I guess your photo evokes emotive thoughts. Plus, it''s very good: 10', '2008-09-18 22:28:20.000000', NULL, 1),
(4962945, 722192, 62187, '<td valign="top">Well then for Christs sake man - pull the trigger!</td>', 'Well then for Christs sake man - pull the trigger!', '2008-09-18 22:29:37.000000', NULL, 1),
(4962948, 722262, 62187, '<td valign="top">One reason I moved to the desert 15 years ago - fits the challenge very well and nice photo. Hope everything else fared well. 8</td>', 'One reason I moved to the desert 15 years ago - fits the challenge very well and nice photo. Hope everything else fared well. 8', '2008-09-18 22:30:52.000000', NULL, 1),
(4962953, 722292, 62187, '<td valign="top">Meets the challenge well - just not a very exciting photo to me. 7</td>', 'Meets the challenge well - just not a very exciting photo to me. 7', '2008-09-18 22:32:13.000000', NULL, 1),
(4962959, 722132, 62187, '<td valign="top">Well, I hope you''ve got a least one hand on the wheel.</td>', 'Well, I hope you''ve got a least one hand on the wheel.', '2008-09-18 22:33:59.000000', NULL, 1),
(4962963, 722303, 62187, '<td valign="top">Yeah, I guess there''s no risk in playing football at other levels. I''m sure you have the expressed written permission to use this image. }''&gt;)</td>', 'Yeah, I guess there''s no risk in playing football at other levels. I''m sure you have the expressed written permission to use this image. }''>)', '2008-09-18 22:35:16.000000', NULL, 1),
(4962970, 721187, 62187, '<td valign="top">To me, it''s actually saying ''Safety'' rather then risk. A VERY cool boat!</td>', 'To me, it''s actually saying ''Safety'' rather then risk. A VERY cool boat!', '2008-09-18 22:36:26.000000', NULL, 1),
(4962971, 721711, 62187, '<td valign="top">Another awesome photo that without the title, would be meaningless in this challenge. The photo alone to me says more like ''Lost'' then anything else.</td>', 'Another awesome photo that without the title, would be meaningless in this challenge. The photo alone to me says more like ''Lost'' then anything else.', '2008-09-18 22:37:27.000000', NULL, 1),
(4962973, 721982, 62187, '<td valign="top">I guess it is a risk but without the title, it''s meaning would be kind of lost in the shuffle.</td>', 'I guess it is a risk but without the title, it''s meaning would be kind of lost in the shuffle.', '2008-09-18 22:38:34.000000', NULL, 1),
(4962976, 721314, 62187, '<td valign="top">A little dark to me but what a great photo for the challenge. For me, it kinda has a double risky meaning: 9</td>', 'A little dark to me but what a great photo for the challenge. For me, it kinda has a double risky meaning: 9', '2008-09-18 22:39:22.000000', NULL, 1),
