(4963015, 722192, 25095, '<td valign="top">Fits challenge=5 <br/>Color/lighting=1 <br/>DOF/focus=1 <br/>Wow factor/uniqueness=0 <br/>Attractiveness=0 <br/>comments: Nice shot...pun intended.  Good lighting and focus seems sharp.</td>', 'Fits challenge=5 Color/lighting=1 DOF/focus=1 Wow factor/uniqueness=0 Attractiveness=0 comments: Nice shot...pun intended.  Good lighting and focus seems sharp.', '2008-09-18 23:17:52.000000', NULL, 1),
(4963044, 721758, 62187, '<td valign="top">I''ll bet she knows some ''Ducky Airbags''. As far as this photo, without your title the photo would be meaningless in this challenge...imho</td>', 'I''ll bet she knows some ''Ducky Airbags''. As far as this photo, without your title the photo would be meaningless in this challenge...imho', '2008-09-18 23:48:02.000000', NULL, 1),
(4963052, 721929, 93421, '<td valign="top">Clever title and great DoF</td>', 'Clever title and great DoF', '2008-09-18 23:58:54.000000', NULL, 1),
(4963090, 722130, 62187, '<td valign="top">Very nice focus and shutter speed.</td>', 'Very nice focus and shutter speed.', '2008-09-19 00:38:07.000000', NULL, 1),
